// hop's verdict engine, exposed as an MCP server ("Add to Claude"). External
// LLMs (Claude, etc.) call hop's REAL deterministic engine through these tools —
// proof that the engine, not a prompt, is the moat. Every number is computed by
// lib/* (search/destinations/transfers), never generated by a model.
//
// Transport: streamable HTTP via mcp-handler (Vercel's MCP product). The dynamic
// [transport] segment lets the SDK serve both the streamable-HTTP endpoint
// (/api/mcp) and the legacy SSE endpoint (/api/sse) from one route.
//
// AUTH / LINKING (lib/api-tokens):
//   - No bearer token  -> STATELESS mode. Tools work with caller-supplied
//     balances or return generic/no-balance results. Never another user's data.
//   - hop_ bearer token -> resolves to the owner's Auth0 sub; balance-aware tools
//     load THAT user's real balances via getUserBalances. Auth is optional
//     (required:false) so the server is useful immediately and richer once linked.

import { createMcpHandler, withMcpAuth } from 'mcp-handler'
import type { AuthInfo } from '@modelcontextprotocol/sdk/server/auth/types.js'
import { userIdForToken } from '@/lib/api-tokens'
import { getUserBalances } from '@/lib/accounts'
import {
  priceTripSchema,
  verdictSchema,
  sweetSpotsSchema,
  transferPathsSchema,
  runPriceTrip,
  runVerdict,
  runSweetSpots,
  runTransferPaths,
  type balanceInputSchema,
} from '@/lib/mcp-tools'
import type { z } from 'zod'

type BalanceInput = z.infer<typeof balanceInputSchema>

// The Auth0 sub a request resolved to, if a valid hop token was presented. We
// stash it in AuthInfo.extra.userId from verifyToken below.
function userIdFromExtra(extra: { authInfo?: AuthInfo }): string | undefined {
  const id = extra.authInfo?.extra?.userId
  return typeof id === 'string' ? id : undefined
}

// Resolve the balances to feed a balance-aware tool: caller-supplied balances
// win (explicit + stateless-friendly); otherwise, if the request is linked,
// load the user's REAL balances. Linked-user data is ONLY ever reachable via
// that user's own token, so this can never leak across users.
async function resolveBalances(
  supplied: BalanceInput | undefined,
  userId: string | undefined,
): Promise<BalanceInput | undefined> {
  if (supplied && supplied.length > 0) return supplied
  if (!userId) return supplied
  const real = await getUserBalances(userId)
  return real.map((b) => ({ program: b.program, balance: b.balance }))
}

// Serialize any tool result into the MCP text-content envelope. We return JSON
// text so the calling model gets the full structured object verbatim.
function ok(data: unknown) {
  return { content: [{ type: 'text' as const, text: JSON.stringify(data, null, 2) }] }
}

const handler = createMcpHandler(
  (server) => {
    // price_trip — deterministic miles/CPP/affordability/verdict for one place.
    server.tool(
      'price_trip',
      'Price one destination with hop\'s deterministic engine: typical award miles, cash, cents-per-point (CPP), what you can put toward it (direct or via transfer), affordability, and a points/cash/save verdict. Pass balances or link a hop token for personalized affordability.',
      priceTripSchema,
      async (args, extra) => {
        const balances = await resolveBalances(args.balances, userIdFromExtra(extra))
        return ok(runPriceTrip({ destinationCode: args.destinationCode, balances }))
      },
    )

    // verdict — full points-vs-cash call for a route (runs assembleSearch).
    server.tool(
      'verdict',
      'Run hop\'s full points-vs-cash verdict for a route. Returns the verdict (use-points / pay-cash / none), a summary (cheapest cash, best miles, best CPP, $ saved vs cash), the chosen pick, and the top options. Pass balances or link a hop token for a personalized "you have" call.',
      verdictSchema,
      async (args, extra) => {
        const balances = await resolveBalances(args.balances, userIdFromExtra(extra))
        return ok(
          await runVerdict({
            from: args.from,
            to: args.to,
            depart: args.depart,
            return: args.return,
            adults: args.adults,
            balances,
          }),
        )
      },
    )

    // sweet_spots — top-value redemptions by CPP.
    server.tool(
      'sweet_spots',
      'List hop\'s top-value award redemptions ("sweet spots") ranked by cents-per-point: destination, best program, miles needed, typical cash, and CPP.',
      sweetSpotsSchema,
      async (args) => ok(runSweetSpots({ limit: args.limit })),
    )

    // transfer_paths — transfer reachability for a program.
    server.tool(
      'transfer_paths',
      'Show transfer paths for a program. For a bank currency (Amex/Chase/Citi/Cap One/Bilt) returns its outbound partners with ratios; for an airline/hotel program returns which bank currencies can reach it.',
      transferPathsSchema,
      async (args) => ok(runTransferPaths({ program: args.program })),
    )
  },
  {
    // Server identity surfaced to clients during initialize.
    serverInfo: { name: 'hop', version: '1.0.0' },
  },
  {
    basePath: '/api',
    verboseLogs: false,
  },
)

// Bearer-token auth, OPTIONAL. A presented hop_ token resolves to its owner's
// Auth0 sub and rides along in AuthInfo.extra.userId; an absent/invalid token
// leaves the request unauthenticated (stateless mode) rather than rejecting it.
const verifyToken = async (
  _req: Request,
  bearerToken?: string,
): Promise<AuthInfo | undefined> => {
  if (!bearerToken) return undefined
  const userId = await userIdForToken(bearerToken)
  if (!userId) return undefined
  return {
    token: bearerToken,
    clientId: userId,
    scopes: ['hop:read'],
    extra: { userId },
  }
}

const authedHandler = withMcpAuth(handler, verifyToken, { required: false })

export { authedHandler as GET, authedHandler as POST, authedHandler as DELETE }
